const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{ .name = "app", .root_module = mod });
    b.installArtifact(exe);

    const run = b.addRunArtifact(exe);
    if (b.args) |args| run.addArgs(args);
    b.step("run", "Run the server").dependOn(&run.step);

    const tests = b.addTest(.{ .root_module = mod });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! Thread-safe in-memory key-value store. Keys and values are owned by the
//! store and allocated with its allocator.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

const Store = @This();

gpa: Allocator,
lock: Io.RwLock = .init,
map: std.StringHashMapUnmanaged([]u8) = .empty,

pub fn init(gpa: Allocator) Store {
    return .{ .gpa = gpa };
}

pub fn deinit(store: *Store) void {
    var it = store.map.iterator();
    while (it.next()) |entry| {
        store.gpa.free(entry.key_ptr.*);
        store.gpa.free(entry.value_ptr.*);
    }
    store.map.deinit(store.gpa);
    store.* = undefined;
}

pub const PutResult = enum { created, replaced };

/// Stores `value`, taking ownership of it (it must have been allocated with
/// the store's allocator). `key` is copied.
pub fn put(store: *Store, io: Io, key: []const u8, value: []u8) (Allocator.Error || Io.Cancelable)!PutResult {
    errdefer store.gpa.free(value);
    // Allocate outside the critical section; freed below if the key exists.
    const owned_key = try store.gpa.dupe(u8, key);
    var key_used = false;
    defer if (!key_used) store.gpa.free(owned_key);

    try store.lock.lock(io);
    defer store.lock.unlock(io);

    const gop = try store.map.getOrPut(store.gpa, owned_key);
    if (gop.found_existing) {
        store.gpa.free(gop.value_ptr.*);
        gop.value_ptr.* = value;
        return .replaced;
    }
    key_used = true;
    gop.value_ptr.* = value;
    return .created;
}

/// Returns a copy of the value for `key`, owned by the caller and allocated
/// with `gpa`, or null if the key is absent.
pub fn getCopy(store: *Store, io: Io, gpa: Allocator, key: []const u8) (Allocator.Error || Io.Cancelable)!?[]u8 {
    try store.lock.lockShared(io);
    defer store.lock.unlockShared(io);
    const value = store.map.get(key) orelse return null;
    return try gpa.dupe(u8, value);
}

/// Returns whether the key was present.
pub fn delete(store: *Store, io: Io, key: []const u8) Io.Cancelable!bool {
    try store.lock.lock(io);
    defer store.lock.unlock(io);
    const kv = store.map.fetchRemove(key) orelse return false;
    store.gpa.free(kv.key);
    store.gpa.free(kv.value);
    return true;
}

/// Writes every key, sorted ascending, as a JSON array of strings.
pub fn writeKeysJson(store: *Store, io: Io, gpa: Allocator, w: *Io.Writer) (Allocator.Error || Io.Writer.Error || Io.Cancelable)!void {
    try store.lock.lockShared(io);
    defer store.lock.unlockShared(io);

    const keys = try gpa.alloc([]const u8, store.map.count());
    defer gpa.free(keys);
    var it = store.map.keyIterator();
    var i: usize = 0;
    while (it.next()) |k| : (i += 1) keys[i] = k.*;

    std.mem.sortUnstable([]const u8, keys, {}, lessThan);
    try std.json.Stringify.value(keys, .{}, w);
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.lessThan(u8, a, b);
}

test "put, get, delete, list" {
    const io = std.testing.io;
    const gpa = std.testing.allocator;
    var store: Store = .init(gpa);
    defer store.deinit();

    try std.testing.expectEqual(.created, try store.put(io, "b", try gpa.dupe(u8, "1")));
    try std.testing.expectEqual(.replaced, try store.put(io, "b", try gpa.dupe(u8, "2")));
    try std.testing.expectEqual(.created, try store.put(io, "a", try gpa.dupe(u8, "")));

    const v = (try store.getCopy(io, gpa, "b")).?;
    defer gpa.free(v);
    try std.testing.expectEqualStrings("2", v);
    try std.testing.expectEqual(null, try store.getCopy(io, gpa, "zz"));

    var out: Io.Writer.Allocating = .init(gpa);
    defer out.deinit();
    try store.writeKeysJson(io, gpa, &out.writer);
    try std.testing.expectEqualStrings("[\"a\",\"b\"]", out.written());

    try std.testing.expect(try store.delete(io, "a"));
    try std.testing.expect(!try store.delete(io, "a"));
}

//! kvhttp: an in-memory key-value store served over HTTP/1.1.
//!
//! Usage: app <port>   (listens on 127.0.0.1:<port>)

const std = @import("std");
const Io = std.Io;
const http = std.http;
const Allocator = std.mem.Allocator;
const Request = http.Server.Request;

const Store = @import("Store.zig");
const routing = @import("routing.zig");

const log = std.log.scoped(.kvhttp);

pub const max_value_len = 1024 * 1024;
/// Upper bound on the size of a request head (request line plus headers).
const max_head_len = 16 * 1024;

pub const std_options: std.Options = .{ .log_level = .warn };

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const gpa = init.gpa;

    var args = init.minimal.args.iterate();
    _ = args.skip();
    const port_arg = args.next() orelse fatal("usage: app <port>", .{});
    const port = std.fmt.parseInt(u16, port_arg, 10) catch fatal("invalid port: {s}", .{port_arg});

    const address: Io.net.IpAddress = .{ .ip4 = .loopback(port) };
    var listener = address.listen(io, .{ .reuse_address = true }) catch |err|
        fatal("cannot listen on 127.0.0.1:{d}: {t}", .{ port, err });
    defer listener.deinit(io);

    var store: Store = .init(gpa);
    defer store.deinit();

    var connections: Io.Group = .init;
    defer connections.cancel(io);

    while (true) {
        const stream = listener.accept(io) catch |err| switch (err) {
            error.Canceled => return,
            else => {
                log.warn("accept failed: {t}", .{err});
                continue;
            },
        };
        connections.concurrent(io, handleConnection, .{ io, gpa, &store, stream }) catch {
            // No spare concurrency; serve this client inline rather than drop it.
            handleConnection(io, gpa, &store, stream);
        };
    }
}

fn fatal(comptime fmt: []const u8, args: anytype) noreturn {
    std.log.err(fmt, args);
    std.process.exit(1);
}

const Connection = struct {
    io: Io,
    gpa: Allocator,
    store: *Store,
    server: *http.Server,
};

fn handleConnection(io: Io, gpa: Allocator, store: *Store, stream: Io.net.Stream) void {
    defer stream.close(io);

    var recv_buffer: [max_head_len]u8 = undefined;
    var send_buffer: [4096]u8 = undefined;
    var stream_reader = stream.reader(io, &recv_buffer);
    var stream_writer = stream.writer(io, &send_buffer);
    var server: http.Server = .init(&stream_reader.interface, &stream_writer.interface);

    const conn: Connection = .{ .io = io, .gpa = gpa, .store = store, .server = &server };
    while (true) {
        const keep_alive = serveRequest(conn) catch |err| {
            switch (err) {
                error.ReadFailed => if (stream_reader.err) |e| log.debug("read: {t}", .{e}),
                error.WriteFailed => if (stream_writer.err) |e| log.debug("write: {t}", .{e}),
                else => log.debug("connection error: {t}", .{err}),
            }
            return;
        };
        if (!keep_alive) return;
    }
}

const ServeError = Allocator.Error || Io.Cancelable || Io.Writer.Error || Io.Reader.Error ||
    Request.ExpectContinueError;

/// Reads and answers one request. Returns whether the connection may be reused.
fn serveRequest(conn: Connection) ServeError!bool {
    const server = conn.server;
    const head_buffer = server.reader.receiveHead() catch |err| switch (err) {
        error.HttpConnectionClosing, error.HttpRequestTruncated => return false,
        error.HttpHeadersOversize => {
            try writeBareResponse(server.out, .request_header_fields_too_large);
            return false;
        },
        error.ReadFailed => |e| return e,
    };

    const head = Request.Head.parse(head_buffer) catch |err| {
        // std.http only knows the standard methods; any other token still
        // deserves 404/400/405 according to the path it targets.
        const status: http.Status = switch (err) {
            error.UnknownHttpMethod => unknownMethodStatus(head_buffer),
            error.HttpTransferEncodingUnsupported, error.CompressionUnsupported => .not_implemented,
            else => .bad_request,
        };
        try writeBareResponse(server.out, status);
        return false;
    };
    var request: Request = .{ .server = server, .head = head, .head_buffer = head_buffer };

    if (request.head.expect) |expect| {
        if (!std.ascii.eqlIgnoreCase(expect, "100-continue")) {
            request.head.expect = null;
            try respond(&request, .expectation_failed, "", .{ .keep_alive = false });
            return false;
        }
        // Expectation tokens are case-insensitive, but std.http compares exactly.
        request.head.expect = "100-continue";
    }

    const route = switch (routing.resolve(@tagName(request.head.method), request.head.target)) {
        .route => |r| r,
        .reject => |status| {
            try discardBody(&request);
            try respond(&request, status, "", .{});
            return request.head.keep_alive;
        },
    };

    switch (route) {
        .health => {
            try discardBody(&request);
            try respond(&request, .ok, "ok", .{ .content_type = "text/plain" });
        },
        .list => {
            try discardBody(&request);
            var json: Io.Writer.Allocating = .init(conn.gpa);
            defer json.deinit();
            conn.store.writeKeysJson(conn.io, conn.gpa, &json.writer) catch |err| switch (err) {
                error.WriteFailed => return error.OutOfMemory,
                else => |e| return e,
            };
            try respond(&request, .ok, json.written(), .{ .content_type = "application/json" });
        },
        .get => |key| {
            try discardBody(&request);
            if (try conn.store.getCopy(conn.io, conn.gpa, key.slice())) |value| {
                defer conn.gpa.free(value);
                try respond(&request, .ok, value, .{ .content_type = "application/octet-stream" });
            } else {
                try respond(&request, .not_found, "", .{});
            }
        },
        .delete => |key| {
            try discardBody(&request);
            const status: http.Status = if (try conn.store.delete(conn.io, key.slice())) .no_content else .not_found;
            try respond(&request, status, "", .{});
        },
        .put => |key| {
            const value = readValue(conn.gpa, &request) catch |err| switch (err) {
                error.ValueTooLarge => {
                    try respond(&request, .payload_too_large, "", .{ .keep_alive = false });
                    return false;
                },
                else => |e| return e,
            };
            const status: http.Status = switch (try conn.store.put(conn.io, key.slice(), value)) {
                .created => .created,
                .replaced => .ok,
            };
            try respond(&request, status, "", .{});
        },
    }
    return request.head.keep_alive;
}

/// Prepares to read the request body, whatever the method. Reading it all
/// (rather than leaving bytes unread) matters even when closing: closing a
/// socket with unread input makes the kernel send RST, which can destroy the
/// response before the client reads it.
///
/// Invalidates the string memory in `request.head`.
fn bodyReader(request: *Request) Request.ExpectContinueError!*Io.Reader {
    const head = &request.head;
    if (head.transfer_encoding == .none and head.content_length == null) {
        // No body; the next request (if any) starts right after the head.
        head.expect = null;
        request.server.reader.state = .ready;
        return Io.Reader.ending;
    }
    if (head.expect != null) {
        try request.writeExpectContinue();
        try request.server.out.flush();
    }
    return request.server.reader.bodyReader(&.{}, head.transfer_encoding, head.content_length);
}

fn discardBody(request: *Request) ServeError!void {
    const body = try bodyReader(request);
    _ = try body.discardRemaining();
}

/// Reads the request body into a buffer owned by the caller.
fn readValue(gpa: Allocator, request: *Request) (ServeError || error{ValueTooLarge})![]u8 {
    if (request.head.content_length) |len| {
        if (len > max_value_len) return error.ValueTooLarge;
    }
    const known_len = request.head.content_length;
    const body = try bodyReader(request);
    if (known_len) |len| {
        const value = try gpa.alloc(u8, @intCast(len));
        errdefer gpa.free(value);
        try body.readSliceAll(value);
        return value;
    }
    return body.allocRemaining(gpa, .limited(max_value_len + 1)) catch |err| switch (err) {
        error.StreamTooLong => error.ValueTooLarge,
        else => |e| e,
    };
}

const RespondOptions = struct {
    content_type: ?[]const u8 = null,
    keep_alive: bool = true,
};

fn respond(request: *Request, status: http.Status, body: []const u8, options: RespondOptions) Request.ExpectContinueError!void {
    var headers_buf: [1]http.Header = undefined;
    var headers: []const http.Header = &.{};
    if (options.content_type) |ct| {
        headers_buf[0] = .{ .name = "content-type", .value = ct };
        headers = &headers_buf;
    }
    try request.respond(body, .{
        .status = status,
        .keep_alive = options.keep_alive,
        .extra_headers = headers,
    });
}

/// Writes a body-less response and signals that the connection will close.
/// Used when the request head could not be parsed into a `Request`.
fn writeBareResponse(out: *Io.Writer, status: http.Status) Io.Writer.Error!void {
    try out.print("HTTP/1.1 {d} {s}\r\ncontent-length: 0\r\nconnection: close\r\n\r\n", .{
        @intFromEnum(status), status.phrase() orelse "",
    });
    try out.flush();
}

fn unknownMethodStatus(head_buffer: []const u8) http.Status {
    const line_end = std.mem.indexOf(u8, head_buffer, "\r\n") orelse head_buffer.len;
    var parts = std.mem.tokenizeScalar(u8, head_buffer[0..line_end], ' ');
    const method = parts.next() orelse return .bad_request;
    const target = parts.next() orelse return .bad_request;
    return switch (routing.resolve(method, target)) {
        .reject => |status| status,
        // Only standard methods map to routes, and those parse successfully.
        .route => .method_not_allowed,
    };
}

test unknownMethodStatus {
    try std.testing.expectEqual(.method_not_allowed, unknownMethodStatus("FROB /kv/a HTTP/1.1\r\n\r\n"));
    try std.testing.expectEqual(.bad_request, unknownMethodStatus("FROB /kv/a.b HTTP/1.1\r\n\r\n"));
    try std.testing.expectEqual(.not_found, unknownMethodStatus("FROB /x HTTP/1.1\r\n\r\n"));
}

test {
    _ = Store;
    _ = routing;
}

//! Maps a request method and target to an API operation, or to the error
//! status that must be returned instead. Pure; no I/O.

const std = @import("std");
const Status = std.http.Status;

pub const max_key_len = 64;

/// A validated key, copied out of the request head (whose memory is
/// invalidated once the body is read).
pub const Key = struct {
    buf: [max_key_len]u8,
    len: u8,

    pub fn parse(s: []const u8) ?Key {
        if (s.len == 0 or s.len > max_key_len) return null;
        for (s) |c| if (!isKeyChar(c)) return null;
        var k: Key = .{ .buf = undefined, .len = @intCast(s.len) };
        @memcpy(k.buf[0..s.len], s);
        return k;
    }

    pub fn slice(k: *const Key) []const u8 {
        return k.buf[0..k.len];
    }

    fn isKeyChar(c: u8) bool {
        return std.ascii.isAlphanumeric(c) or c == '_' or c == '-';
    }
};

pub const Route = union(enum) {
    health,
    list,
    get: Key,
    put: Key,
    delete: Key,
};

pub const Resolution = union(enum) {
    route: Route,
    /// The request cannot be served; respond with this status.
    reject: Status,
};

/// `method` is the raw method token, so unknown methods route uniformly.
pub fn resolve(method: []const u8, target: []const u8) Resolution {
    const eql = std.mem.eql;
    const kv_prefix = "/kv/";

    if (eql(u8, target, "/health")) {
        return if (eql(u8, method, "GET")) .{ .route = .health } else .{ .reject = .method_not_allowed };
    }
    if (eql(u8, target, "/kv")) {
        return if (eql(u8, method, "GET")) .{ .route = .list } else .{ .reject = .method_not_allowed };
    }
    if (std.mem.startsWith(u8, target, kv_prefix)) {
        const key = Key.parse(target[kv_prefix.len..]) orelse return .{ .reject = .bad_request };
        if (eql(u8, method, "GET")) return .{ .route = .{ .get = key } };
        if (eql(u8, method, "PUT")) return .{ .route = .{ .put = key } };
        if (eql(u8, method, "DELETE")) return .{ .route = .{ .delete = key } };
        return .{ .reject = .method_not_allowed };
    }
    return .{ .reject = .not_found };
}

const testing = std.testing;

fn expectReject(want: Status, method: []const u8, target: []const u8) !void {
    try testing.expectEqual(Resolution{ .reject = want }, resolve(method, target));
}

fn expectKeyRoute(comptime tag: std.meta.Tag(Route), method: []const u8, target: []const u8, key: []const u8) !void {
    const res = resolve(method, target);
    try testing.expect(res == .route and res.route == tag);
    try testing.expectEqualStrings(key, @field(res.route, @tagName(tag)).slice());
}

test "static routes" {
    try testing.expectEqual(Resolution{ .route = .health }, resolve("GET", "/health"));
    try testing.expectEqual(Resolution{ .route = .list }, resolve("GET", "/kv"));
    try expectReject(.method_not_allowed, "POST", "/health");
    try expectReject(.method_not_allowed, "HEAD", "/health");
    try expectReject(.method_not_allowed, "PUT", "/kv");
    try expectReject(.method_not_allowed, "FROB", "/kv");
}

test "key routes" {
    try expectKeyRoute(.get, "GET", "/kv/a", "a");
    try expectKeyRoute(.put, "PUT", "/kv/A-z_09", "A-z_09");
    try expectKeyRoute(.delete, "DELETE", "/kv/x", "x");
    try expectKeyRoute(.get, "GET", "/kv/" ++ "k" ** 64, "k" ** 64);
    try expectReject(.method_not_allowed, "PATCH", "/kv/a");
    try expectReject(.method_not_allowed, "POST", "/kv/a");
}

test "invalid keys" {
    try expectReject(.bad_request, "GET", "/kv/");
    try expectReject(.bad_request, "GET", "/kv/bad.key");
    try expectReject(.bad_request, "GET", "/kv/a/b");
    try expectReject(.bad_request, "PUT", "/kv/" ++ "k" ** 65);
    try expectReject(.bad_request, "GET", "/kv/%41");
    try expectReject(.bad_request, "PATCH", "/kv/a b");
}

test "unknown paths" {
    try expectReject(.not_found, "GET", "/");
    try expectReject(.not_found, "GET", "/nope");
    try expectReject(.not_found, "GET", "/kvx");
    try expectReject(.not_found, "GET", "/health/");
    try expectReject(.not_found, "POST", "/kv2/a");
}
